/* GENERAL GPT PROMPT */
/* This function will be called at any time from "Dialog Node" and "Say Message" to generate a dialog */
__gptDialog_getBasePrompt = function (objective) {

// persona definition
    var prompt = `YOUR PERSONA:
You are a ${__persona.botType} working in a company named ${__persona.companyName} with the following specifications:
- Your name is "${__persona.name}"
- Your gender is "${__persona.gender}"
- Your communication style/tone is "${__persona.tone}"
- You will engage with customers ${__persona.interactionStyle}
- Your role in the company is ${__persona.companyRole}
- You are speaking to ${__persona.targetCustomer}
- Your main function is ${__persona.description}
`;

// conditional definition only for voice channel
    if (__conversationType == 'voicebot') {
        if (context.callInfo.direction == 'inbound') {
            prompt += `- You are speaking with the user by phone (phone number:${context.phone}), it is an incoming call.
`;
        } else {
            prompt += `- You are speaking with the user by phone (phone number:${context.phone}), this is an outgoing call.
`;
        }
    }

// general instructions START
    prompt += `

GENERAL INSTRUCTIONS:
- Use clear and concise language.
- Keep your sentences short and to the point, like in a phone call.
- Mimic authentic interpersonal communication.
- Ensure your responses are aligned with the customer's needs.
- Only anwer questions that are within your scope of tasks.
- If user asks for something you can't do, apologize that you can't help with that.
- If you don't know the answer, don't make it up and say you don't know.
- Do not answer any questions that are not within your objective!
- Always communicate in ${__persona.language} language.
`;

// conditional instruction only for voice channel
    if (__conversationType == 'voicebot') {
        prompt += `- Do not use any emoticons during dialogue.
- Do not use markdown, JSON or HTML syntax during dialogue.
`;
    }


// advanced instructions
    if (typeof __advancedInstructions !== 'undefined') {
        prompt += `
ADVANCED INSTRUCTIONS:
${__advancedInstructions}

`;
    }


// general knowledge
    if (typeof __generalKnowledge !== 'undefined') {
        prompt += `
YOUR KNOWLEDGE IS:
${__generalKnowledge}

`;
    }



// company knowledge
    if (typeof __companyInformation !== 'undefined') {
        prompt += `
INFORMATION ABOUT ${__persona.companyName}:
${__companyInformation}

`;
    }


// info about the user
    if (typeof __generalUserInfo !== 'undefined') {
        prompt += `
INFO ABOUT THE USER:
${__generalUserInfo}

`;
    }

// Current date and time in given timezone
    prompt += `Current date is ` + (getCurrentDialogDate().toLocaleDateString(context.language, { timeZone: __timeZone })) + ` and time is ` + (getCurrentDialogDate().toLocaleTimeString(context.language, { timeZone: __timeZone })) +`

`;

// Main objective (passed from "Dialog Node")
    if (objective) {
        prompt += `

Now, your CURRENT OBJECTIVE in the dialog is:
${objective}

`;
    }

    return prompt;
}

