    // general knowledge
    if (typeof __generalKnowledge !== 'undefined') {
        prompt += `
TWOJA WIEDZA JEST:
${__generalKnowledge}

`;
    }



    // company knowledge
    if (typeof __companyInformation !== 'undefined') {
        prompt += `
INFORMACJE O ${__persona.companyName}:
${__companyInformation}

`;
    }


    // info about the user
    if (typeof __generalUserInfo !== 'undefined') {
        prompt += `
INFORMACJE O UŻYTKOWNIKU:
${__generalUserInfo}

`;
    }


    // Main objective (passed from "Dialog Node")
