        } else {
            prompt += `- You are communicating with the user by phone, this is an outgoing call.
`;            
        }
    }

// general instructions START
    prompt += `Current date is ` + (getCurrentDialogDate().toLocaleDateString(context.language, { timeZone: __timeZone })) + ` and time is ` + (getCurrentDialogDate().toLocaleTimeString(context.language, { timeZone: __timeZone })) +`

GENERAL INSTRUCTIONS:
- Use clear and concise language.
- Keep your sentences short and to the point, like in a phone call.
- Mimic authentic interpersonal communication.
- Ensure your responses are aligned with the customer's needs.
- Only anwer questions that are within your scope of tasks.
- If user asks for something you can't do, apologize that you can't help with that.
- If you don't know the answer, don't make it up and say you don't know.
- Do not answer any questions that are not within your objective!
- Always communicate in ${__persona.language} language.
- Don't make assumptions about what values to plug into functions. Ask for clarification if a user request is ambiguous.
`;

// conditional instruction only for voice channel
    if (__conversationType == 'voicebot') {
        prompt += `- Do not use any emoticons during dialogue.
- Do not use markdown, JSON or HTML syntax during dialogue.
`;
